// Actual controller with a minimal DOM adapter; not browser acceptance.
import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {readFileSync} from 'node:fs';import * as model from '../web/model.js';
const source=readFileSync(new URL('../web/app.js',import.meta.url),'utf8');
const controller=source.slice(source.indexOf('let lockGeneration='),source.indexOf('async function api('));
function harness(){
 const elements=new Map(),calls=[],timers=[],rows=[{id:'a',path:'visible/<img>',item:'modified',props:'none',changelist:'x'},{id:'b',path:'hidden/b',item:'normal',props:'none',changelist:'x'}];
 const state={mode:'live',locksEnabled:true,busy:false,failed:false,rows,selected:new Set(['a','b']),workspaceId:'w',selectionVersion:1,snapshotToken:'s'};
 function $(id){if(!elements.has(id))elements.set(id,{value:'',disabled:false,open:false,textContent:'',innerHTML:'',classList:{add(){},remove(){},toggle(){}},setAttribute(){}});return elements.get(id);}
 const scope=()=>({workspaceId:state.workspaceId,selectionVersion:state.selectionVersion,snapshotToken:state.snapshotToken});
 const context=vm.createContext({...model,TextEncoder,Date,state,$,esc:model.safeText,modalView:'',selectionKey:()=>JSON.stringify([...state.selected]),shelfScope:scope,setTimeout:fn=>timers.push(fn),commitFilesMarkup:rs=>rs.map(r=>model.safeText(r.path)).join('|'),modal:(t,c)=>{$('modal').open=true;$('modal-content').innerHTML=c;context.modalView='generic';vm.runInContext('invalidateLock()',context);},notify:m=>calls.push(['notify',m]),log:m=>calls.push(['log',m]),invalidateReads(){},renderPreview(){},render(){},setBusy:b=>state.busy=b,failSnapshot:m=>{state.failed=true;state.rows=[];state.snapshotToken=null;vm.runInContext('invalidateLock()',context);calls.push(['failed',m]);},applySnapshot:p=>{Object.assign(state,p);vm.runInContext('invalidateLock()',context);},api:async(path,body)=>{calls.push([path,body]);return await response(path,body);}});
 let response=async(path,b)=>path.endsWith('preflight')?{...b,mode:'live',contactsRepository:true,expiresIn:120,planToken:'p',files:rows.filter(r=>b.ids.includes(r.id)).map(r=>({...r,fromChangelist:'x',locked:b.action==='unlock',ownedByWorkingCopy:b.action==='unlock',localTokenPresent:b.action==='unlock',staleLocalToken:false,workingRevision:'2',serverLastChangedRevision:'1'}))}:{...scope(),mode:'live',locksEnabled:true,statusRefreshed:true,snapshotToken:'s2',rows,lockResult:{action:'lock',files:rows.map(r=>r.path),outcome:'verified',verified:true,warnings:[]}};
 vm.runInContext(controller,context);return {state,$,calls,timers,context,run:s=>vm.runInContext(s,context),respond:fn=>response=fn};
}
test('open has no requests, exact hidden selection and separate one-use confirm',async()=>{const h=harness();h.run('openLock()');assert.equal(h.calls.length,0);assert.match(h.$('modal-content').innerHTML,/hidden\/b/);assert.match(h.$('modal-content').innerHTML,/&lt;img&gt;/);await h.run('preflightLock()');assert.deepEqual([...h.calls[0][1].ids],['a','b']);assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,0);await h.run('applyLock()');await h.run('applyLock()');assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,1);assert.match(h.$('lock-last-result').textContent,/已核实锁定完成/);});
test('demo, capability disabled and unsafe selection never call preflight',async()=>{for(const edit of [h=>h.state.mode='demo',h=>h.state.locksEnabled=false,h=>h.state.selected=new Set(['unknown'])]){const h=harness();edit(h);h.run('openLock()');await h.run('preflightLock()');assert(!h.calls.some(c=>c[0].startsWith('/api/')));}});
test('input, selection, snapshot, expiry and close invalidate confirmation',async()=>{for(const change of [h=>h.$('lock-comment').value='changed',h=>h.state.selected=new Set(['a']),h=>h.state.snapshotToken='new',h=>h.timers[0](),h=>{h.$('modal').open=false;h.run('invalidateLock()');}]){const h=harness();h.run('openLock()');await h.run('preflightLock()');change(h);await h.run('applyLock()');assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,0);}});
test('late preflight after dismissal never enables confirmation',async()=>{const h=harness();let resolve;h.respond(()=>new Promise(r=>resolve=r));h.run('openLock()');const pending=h.run('preflightLock()');h.$('modal').open=false;h.run('invalidateLock()');resolve({});await pending;assert.equal(h.$('lock-confirm').disabled,true);});
test('transport unknown clears rows and blocks retry even after refresh until inspection',async()=>{const h=harness();h.run('openLock()');await h.run('preflightLock()');h.respond(()=>{throw Error('network');});await h.run('applyLock()');assert.equal(h.state.rows.length,0);assert.match(h.$('lock-last-result').textContent,/原版可信/);Object.assign(h.state,{failed:false,snapshotToken:'new'});assert.equal(h.run('locksAvailable()'),false);});
test('4xx is safe rejection and not unknown outcome',async()=>{const h=harness();h.run('openLock()');await h.run('preflightLock()');h.respond(()=>{throw Object.assign(Error('rejected'),{httpStatus:409});});await h.run('applyLock()');assert.match(h.$('lock-last-result').textContent,/执行前被拒绝/);assert.equal(h.run('lockInspectionRequired'),false);});
test('verified result retained despite close during apply and failed local refresh',async()=>{const h=harness();h.run('openLock()');await h.run('preflightLock()');let resolve;h.respond(()=>new Promise(r=>resolve=r));const pending=h.run('applyLock()');h.$('modal').open=false;h.run('invalidateLock()');resolve({mode:'live',workspaceId:'w',selectionVersion:1,statusRefreshed:false,snapshotToken:null,rows:[],lockResult:{action:'lock',files:['visible/<img>','hidden/b'],outcome:'verified',verified:true,warnings:['status-refresh-failed']}});await pending;assert.match(h.$('lock-last-result').textContent,/已核实锁定完成/);assert.equal(h.state.rows.length,0);assert.equal(h.$('modal').open,false);});
test('double confirm while pending dispatches once; malformed apply is uncertain',async()=>{const h=harness();h.run('openLock()');await h.run('preflightLock()');let resolve;h.respond(()=>new Promise(r=>resolve=r));const pending=h.run('applyLock()');await h.run('applyLock()');assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,1);resolve({mode:'demo'});await pending;assert.match(h.$('lock-last-result').textContent,/结果未知/);assert.equal(h.run('lockInspectionRequired'),true);});
test('actual input callback invalidates plan, and refresh/workspace/selection/close hooks include lock invalidation',async()=>{const h=harness();h.run('openLock()');await h.run('preflightLock()');h.$('lock-comment').oninput();assert.equal(h.$('lock-confirm').disabled,true);await h.run('applyLock()');assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,0);
 for(const pattern of [/function resetWorkspaceScope\(\)\{invalidateLock\(\)/,/async function refresh\(initial=false\)\{\s*if\(state.busy\)return;invalidateLock\(\)/,/if\(changelistSelection!==selectionKey\(\)\).*invalidateLock\(\)/,/addEventListener\('cancel',\(\)=>\{invalidateLock\(\)/,/addEventListener\('close'.*invalidateLock\(\)/])assert.match(source,pattern);
});
test('actual commit field callbacks still invalidate commit confirmation',()=>{
 const code=source.slice(source.indexOf('let commitGeneration='),source.indexOf('let lockGeneration='));const elements=new Map();
 const $=id=>{if(!elements.has(id))elements.set(id,{disabled:false,classList:{remove(){}},value:'',checked:false});return elements.get(id);};
 const context=vm.createContext({...model,$,state:{mode:'live',commitsEnabled:true,snapshotToken:'s',rows:[{id:'a',path:'a',item:'modified',props:'none'}],selected:new Set(['a'])},esc:model.safeText,modal(){},invalidateLock(){},notify(){},document:{querySelectorAll:()=>[]}});vm.runInContext(code,context);vm.runInContext('openCommit()',context);
 for(const [id,event] of [['commit-message','oninput'],['commit-keep','onchange']]){vm.runInContext('commitPlan={};',context);$('commit-confirm').disabled=false;$(id)[event]();assert.equal($('commit-confirm').disabled,true);assert.equal(vm.runInContext('commitPlan',context),null);}
});
